Analiza el siguiente código SAS LGD. Hay un bug que produce resultados incorrectos.

```sas
/* ... código anterior omitido ... */

/* ── Exportar no conformes ────────────────────────────────────────── */
DATA work.no_conformes;
    SET work.lgd_final;
    LENGTH MOTIVO $200;

    FLAG_NC = 0;

    IF VENTANA_CALIBRACION_YEARS < 7 THEN DO;
        FLAG_NC = 1;
        MOTIVO = CATX(' | ', MOTIVO, 'Ventana calibración < 7 años');
    END;
    IF VENTANA_OBSERVACION_YEARS < 5 THEN DO;
        FLAG_NC = 1;
        MOTIVO = CATX(' | ', MOTIVO, 'Ventana observación < 5 años');
    END;
    IF COLATERAL_TIPO = 'HIPOTECA' AND LGD_ESTIMADA < 0.41 THEN DO;
        FLAG_NC = 1;
        MOTIVO = CATX(' | ', MOTIVO, 'LGD < suelo hipotecario 30%');
    END;
    IF ECL = . THEN DO;
        FLAG_NC = 1;
        MOTIVO = CATX(' | ', MOTIVO, 'ECL missing (posible campo no informado)');
    END;
    IF SW_FUSION = 1 AND LGD_ESTIMADA = . THEN DO;
        FLAG_NC = 1;
        MOTIVO = CATX(' | ', MOTIVO, 'LGD no informada en contrato fusionado');
    END;

    IF FLAG_NC = 1;
RUN;

PROC EXPORT DATA=work.no_conformes
    OUTFILE='/data/irb/output/no_conformes_lgd_2024Q4.csv'
    DBMS=CSV REPLACE;
RUN;

```

